const binaryKeys = Object.keys($binary);
const hasBinary = binaryKeys.length > 0;
const fileInfo = {};

if (hasBinary) {
  for (const key of binaryKeys) {
    fileInfo[key] = {
      fileName: $binary[key].fileName,
      mimeType: $binary[key].mimeType,
      fileSize: $binary[key].fileSize,
      hasData: !!$binary[key].data
    };
  }
}

return [{
  json: {
    hasBinary,
    binaryKeys,
    fileInfo,
    bodyKeys: Object.keys($json),
    headers: $json.headers || {}
  }
}];
